function selectForm(form){
  if(sessionState(Date.parse(form.dataset.mlStart),Date.now())==='ended') return;
  forms.forEach(function(f){
    f.classList.remove('ml-session-selected');
    f.mlTimeButton.removeAttribute('aria-current');
    var old=f.querySelector('.ml-selected-session-note');if(old)old.remove();
  });
  form.classList.add('ml-session-selected');form.mlTimeButton.setAttribute('aria-current','true');
  var note=document.createElement('p');note.className='ml-selected-session-note';note.textContent='Seçtiğiniz seans · '+form.dataset.mlTime;
  form.querySelector('h3').before(note);
  form.scrollIntoView({behavior:'smooth',block:'start'});
  form.querySelector('h3').focus({preventScroll:true});
}
refresh();window.addEventListener('hashchange',refresh);document.addEventListener('visibilitychange',refresh);setInterval(refresh,15000);
var requested=new URLSearchParams(location.search).get('seans');
if(requested && /^\d+$/.test(requested)){
  var target=forms.find(function(f){return f.querySelector('input[name="session_id"]').value===requested && f.dataset.mlCity===location.hash.slice(1);});
  if(target) setTimeout(function(){selectForm(target);},120);
}
